(function(){
'use strict';
function ui(){return S.materialPolish||(S.materialPolish={closed:{},draft:null,next:null});}
function target(){const f=curContentFile();if(!f)return null;const result=(f.contentResults||[]).find(a=>a.id===S.materialFolders.contentResult);return {f,result,key:f.id+':'+(result?.id||'main'),text:result?result.md:(f.contentMd??f.md??'')};}
function editable(t){return t&&t.f.status==='fileFinal'&&!S.materialBulk?.job?.running;}
function dirty(){const d=ui().draft;return d&&d.text!==d.before;}
window.v11Guard=function(fn){if(!dirty()){ui().draft=null;fn();return;}ui().next=fn;modal('<div class="m-head">有未保存修改</div><div class="m-body">请先保存，或放弃当前编辑再继续。</div><div class="m-foot"><button onclick="closeModal();S.materialPolish.next=null">继续编辑</button><button onclick="v11LeaveEdit(false)">放弃并继续</button><button onclick="v11LeaveEdit(true)">保存并继续</button></div>');};
window.v11LeaveEdit=function(save){const next=ui().next;if(save&&!saveDraft())return;ui().draft=null;ui().next=null;S.contentViewMode='preview';closeModal();if(next)next();};
function saveDraft(){const d=ui().draft,t=target();if(!d||!editable(t)||d.project!==S.proj?.id||d.key!==t.key||d.before!==t.text||d.source!==t.f.md){toast('文件状态或内容已变化，未保存；请保留编辑内容后重新核对','warn');return false;}if(t.result)t.result.md=d.text;else t.f.contentMd=d.text;logEvent('stage.material',(t.result?.name||t.f.mdPath||t.f.name)+' 人工编辑保存');ui().draft=null;return true;}
window.v11ContentMode=function(mode){if(mode!=='edit'){v11Guard(()=>{S.contentViewMode=mode;render();});return;}const t=target();if(!editable(t)){toast('请先完成文件解析定稿；内容已定稿需先解锁','warn');return;}if(!ui().draft)ui().draft={key:t.key,project:S.proj.id,before:t.text,text:t.text,source:t.f.md};S.contentViewMode='edit';render();};
window.v11SaveContent=function(){if(saveDraft()){S.contentViewMode='preview';render();}};
window.v11CancelContent=function(){ui().draft=null;S.contentViewMode='preview';render();};
window.v11ToggleRoot=function(kind){ui().closed[kind]=!ui().closed[kind];render();};
window.v11ToggleResults=function(id){ui().closed['results:'+id]=!ui().closed['results:'+id];render();};
function rootButton(kind,label){return '<button class="ghost root-toggle" data-root-toggle="'+kind+'" aria-expanded="'+!ui().closed[kind]+'" onclick="v11ToggleRoot(\''+kind+'\')">'+(ui().closed[kind]?'▸':'▾')+' 📁 '+label+'</button>';}
const oldFile=window.matFileHtml;window.matFileHtml=function(){const t=document.createElement('template');t.innerHTML=oldFile();for(const kind of ['original','parsed']){const list=t.content.querySelector('[data-material-root="'+kind+'"]'),bar=list.previousElementSibling,head=bar.previousElementSibling;const filter=head.querySelector('label');head.innerHTML=rootButton(kind,kind==='original'?'原始文件':'解析文件');if(filter)head.append(filter);list.hidden=!!ui().closed[kind];}return t.innerHTML;};
const oldContent=window.matContentHtml;window.matContentHtml=function(){const t=document.createElement('template');t.innerHTML=oldContent();const left=t.content.querySelector('.panel-left');left.classList.add('material-content-nav');left.querySelector('.pl-head').innerHTML=rootButton('content','解析文件');const list=left.querySelector('.filelist');list.hidden=!!ui().closed.content;list.querySelectorAll('[data-content-file]').forEach(button=>{const wrap=button.parentElement,id=button.dataset.contentFile,f=S.files.find(x=>x.id===id);wrap.className='content-file-row';wrap.removeAttribute('style');button.removeAttribute('style');button.classList.add('content-file-open');for(const node of [...button.childNodes])if(node.nodeType===3)node.remove();button.title=f.mdPath||f.name;const label=button.querySelector('.fn');if(label)label.textContent=(f.mdPath||f.name).split('/').at(-1);if(f.contentResults?.length){const toggle=document.createElement('button');toggle.className='ghost result-toggle';toggle.textContent=ui().closed['results:'+id]?'▸':'▾';toggle.setAttribute('aria-label','展开收拢加工结果');toggle.setAttribute('onclick',"v11ToggleResults('"+id+"')");wrap.insertBefore(toggle,button);for(const r of f.contentResults){const child=list.querySelector('[data-content-result="'+r.id+'"]');if(child){child.hidden=!!ui().closed['results:'+id];child.classList.add('content-result-row');child.title=r.name;child.textContent='↳ '+r.name.split('/').at(-1);}}}});const report=left.querySelector('section');if(report){const details=document.createElement('details');details.open=!ui().closed.report;details.setAttribute('ontoggle','S.materialPolish.closed.report=!this.open');details.innerHTML='<summary style="padding:10px">批量任务结果</summary>';report.before(details);details.append(report);}
const current=target(),modes=t.content.querySelector('.doc-toolbar .viewmode');if(modes){modes.innerHTML=[['preview','预览'],['edit','编辑'],['src','Markdown 源码']].map(([key,label])=>'<button '+(key==='edit'&&!editable(current)?'disabled ':'')+'class="'+(S.contentViewMode===key?'active':'')+'" onclick="v11ContentMode(\''+key+'\')">'+label+'</button>').join('');}if(S.contentViewMode==='edit'&&current){const d=ui().draft,body=t.content.querySelector('.doc-scroll');if(body)body.innerHTML=d&&d.key===current.key?'<div class="doc-paper"><textarea id="content-editor" class="md-editor" oninput="S.materialPolish.draft.text=this.value">'+esc(d.text)+'</textarea><div class="content-edit-actions"><button onclick="v11CancelContent()">取消编辑</button><button class="primary" onclick="v11SaveContent()" '+(!editable(current)?'disabled':'')+'>保存</button></div></div>':'<div class="doc-paper">编辑目标已变化，请切回预览后重新编辑。</div>';}
return t.innerHTML;};
for(const name of ['v11OpenContent','v11Open','openProject','go','v11BulkDialog','v11BulkContentFinal','runOp','finalContent','v11ContentDownload','v11BatchFinal']){const old=window[name];if(typeof old==='function')window[name]=function(){const args=arguments;v11Guard(()=>old.apply(this,args));};}
const oldView=window.viewMaterial;window.viewMaterial=function(){const t=document.createElement('template');t.innerHTML=oldView();t.content.querySelectorAll('.subtab').forEach((button,i)=>button.setAttribute('onclick',"v11SwitchMaterial('"+(i===0?'file':'content')+"')"));return t.innerHTML;};
window.v11SwitchMaterial=function(tab){v11Guard(()=>{S.matTab=tab;S.contentViewMode='preview';S.quote=null;render();});};
})();
